import { describe, it } from "vitest";

// Observable contract for rejection cases:
// The specification states that invalid scenarios make the CLI exit with a
// non-zero status code and write an error description to stderr. The domain
// layer expresses this by throwing an Error; the CLI adapter translates a
// thrown Error into exit code 1 plus an stderr message. This reading is stated
// explicitly here because the specification defines the CLI-level contract but
// not the in-process one, and it does not establish any specific error type or
// message text.

describe("MHPCO Claim Office", () => {
  // --- Quote: simplest case ---
  it.todo("quotes an empty item list as premium 5 G (processing fee only)");

  // --- Quote: base premiums per main item type (parallel price-list catalogue) ---
  it.todo("quotes a plain sword as premium 105 G (100 G base + 5 G fee)");
  it.todo("quotes a plain amulet as premium 65 G (60 G base + 5 G fee)");
  it.todo("quotes a plain staff as premium 85 G (80 G base + 5 G fee)");
  it.todo("quotes a plain potion as premium 45 G (40 G base + 5 G fee)");

  // --- Quote: component base premiums (parallel component catalogue) ---
  it.todo("quotes a single rune as premium 30 G (25 G base + 5 G fee)");
  it.todo("quotes a single moonstone as premium 30 G (25 G base + 5 G fee)");

  // --- Quote: building block of 3 alike components ---
  it.todo("quotes 2 runes as base premium 50 G (no block)");
  it.todo("quotes 3 runes as base premium 60 G (block applies)");
  it.todo("quotes 4 runes as base premium 100 G (no block -- block requires exactly 3)");
  it.todo("quotes 7 runes as base premium 175 G (no block -- block requires exactly 3)");

  // --- Quote: "alike" means same component type, not same family ---
  it.todo("quotes 2 runes + 1 moonstone as base premium 75 G (no block: different types)");
  it.todo("quotes 3 runes + 3 moonstones as base premium 120 G (two separate blocks)");

  // --- Quote: item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge to a cursed sword -- base premium 150 G");
  it.todo("adds a 30 % high-enchantment surcharge to a sword with enchantment 5 -- base premium 130 G");
  it.todo("adds no high-enchantment surcharge to a sword with enchantment 4 -- base premium 100 G");
  it.todo("adds both surcharges to a cursed sword with enchantment 5 -- base premium 180 G");

  // --- Quote: item-specific modifier scope on multi-item policies ---
  it.todo("applies the curse surcharge only to the cursed item: cursed sword + plain amulet -> 210 G before policy modifiers and fee");

  // --- Quote: policy-wide modifiers ---
  it.todo("applies a 20 % loyalty discount for a customer with exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount for a customer with 1 year with MHPCO");
  it.todo("applies a 10 % first-insurance surcharge to each item in a quote");
  it.todo("applies a 15 % follow-up discount to the customer's second quote in a scenario");
  it.todo("applies no follow-up discount to the customer's first quote in a scenario");
  it.todo("applies the first-insurance surcharge on a follow-up contract too (each quoted item is a first insurance)");

  // --- Quote: rounding in the MHPCO's favour ---
  it.todo("rounds a premium of 197.5 G up to 198 G");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Quote: integration examples ---
  it.todo("quotes a newcomer's cursed steel sword (enchantment 3, 0 years) as premium 165 G");
  it.todo("quotes a 3-year customer's second contract for a cursed sword (enchantment 7) as premium 160 G");

  // --- Quote: rejection ---
  it.todo("rejects a quote containing an item with an unknown type (e.g. broomstick) by throwing an Error");

  // --- Claim: insurance sum and cap ---
  it.todo("caps a sword policy at 2000 G (2 x insurance sum 1000 G)");
  it.todo("caps a sword + amulet policy at 3200 G (2 x insurance sum 1600 G)");
  it.todo("caps a two-sword policy at 4000 G (2 x insurance sum 2000 G)");
  it.todo("bases the cap on unmodified insurance values: cursed sword -> cap 2000 G despite premium 165 G");
  it.todo("bases the insurance sum on undiscounted item values: sword + 3 runes -> insurance sum 1750 G, cap 3500 G");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("pays 400 G for 500 G damage to a regular steel sword with enchantment 3 (full minus 100 G deductible)");
  it.todo("pays 100 G for 200 G damage to a rune (no enchantment or material -> no special clause)");

  // --- Claim: special clauses ---
  it.todo("pays 400 G for 1000 G damage to a steel sword with enchantment 9 (50 % clause, then deductible)");
  it.todo("pays 400 G for 1000 G damage to a dragon sword with exactly enchantment 8 (50 % clause, then deductible)");
  it.todo("pays 700 G for 800 G damage to a dragon sword with enchantment 5 (full reimbursement, then deductible)");
  it.todo("pays 400 G for 1000 G damage to a dragon sword with enchantment 9 (50 % clause wins, then deductible)");

  // --- Claim: deductible per damage event ---
  it.todo("applies the 100 G deductible once per damaged item: sword 500 G + amulet 300 G -> payout 600 G");

  // --- Claim: multiple items of the same type ---
  it.todo("treats two sword damage entries on a two-sword policy as separate damages with their own deductibles");
  it.todo("rejects a claim with more damage entries of a type than the policy covers by throwing an Error");

  // --- Claim: cap exhaustion across successive claims ---
  it.todo("pays 1400 G on a first 1500 G claim against a sword policy, leaving cap 600 G");
  it.todo("reduces a second 1500 G claim to the remaining cap 600 G, leaving cap 0 G");

  // --- Claim: rounding in the MHPCO's favour ---
  it.todo("rounds a payout of 350.5 G down to 350 G");

  // --- Claim: rejection ---
  it.todo("rejects a claim whose damaged item is not part of the policy (amulet damaged, only a sword insured) by throwing an Error");
  it.todo("rejects a claim whose damaged item has an unknown type by throwing an Error");
  it.todo("rejects a claim containing a damage entry with amount -200 by throwing an Error");

  // --- CLI adapter ---
  it.todo("CLI reads a scenario from stdin and writes {results:[{premium},{payout,remainingCap}]} to stdout");
  it.todo("CLI exits with a non-zero status code and writes an error description to stderr for an invalid scenario, writing no results to stdout");
});

