 28	interface PriceListEntry {
 29	  basePremium: number;
 30	  insuranceValue: number;
 31	}
 32	
 33	// The MHPCO price list: what the office insures, and on what terms.
 34	const MAIN_ITEM_PRICE_LIST: Record<string, PriceListEntry> = {
 35	  sword: {
 36	    basePremium: SWORD_BASE_PREMIUM,
 37	    insuranceValue: SWORD_INSURANCE_VALUE,
 38	  },
 39	  amulet: {
 40	    basePremium: AMULET_BASE_PREMIUM,
