 48	    basePremium: POTION_BASE_PREMIUM,
 49	    insuranceValue: POTION_INSURANCE_VALUE,
 50	  },
 51	};
 52	
 53	const COMPONENT_TYPES: ReadonlySet<string> = new Set(["rune", "moonstone"]);
 54	
 55	function isComponent(type: string): boolean {
 56	  return COMPONENT_TYPES.has(type);
 57	}
 58	
 59	export interface Item {
 60	  type: string;
 61	  material?: string;
 62	  enchantment?: number;
 63	  cursed?: boolean;
 64	}
 65	
 66	export interface QuoteStep {
 67	  op: "quote";
 68	  items: Item[];
 69	}
 70	
 71	export interface Damage {
 72	  itemType: string;
 73	  amount: number;
 74	}
 75	
 76	export interface Incident {
 77	  cause: string;
 78	  damages: Damage[];
 79	}
 80	
 81	export interface ClaimStep {
 82	  op: "claim";
 83	  policy: number;
 84	  incident: Incident;
 85	}
 86	
 87	export type Step = QuoteStep | ClaimStep;
 88	
 89	export interface Customer {
 90	  yearsWithMHPCO: number;
 91	}
 92	
 93	export interface Scenario {
 94	  customer: Customer;
 95	  steps: Step[];
 96	}
 97	
 98	export interface QuoteResult {
 99	  premium: number;
100	}
101	
102	export interface ClaimResult {
103	  payout: number;
104	  remainingCap: number;
105	}
106	
107	export type StepResult = QuoteResult | ClaimResult;
108	
109	function isInsurable(type: string): boolean {
110	  return isComponent(type) || type in MAIN_ITEM_PRICE_LIST;
111	}
112	
113	function requireInsurable(type: string): void {
114	  if (!isInsurable(type)) {
115	    throw new Error(`The MHPCO does not insure items of type "${type}"`);
116	  }
117	}
118	
119	function basePremiumOf(item: Item): number {
120	  if (isComponent(item.type)) {
121	    return COMPONENT_BASE_PREMIUM;
122	  }
123	  return MAIN_ITEM_PRICE_LIST[item.type].basePremium;
124	}
125	
126	function countByType(items: Item[]): Map<string, number> {
127	  const counts = new Map<string, number>();
128	  for (const item of items) {
129	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
130	  }
131	  return counts;
132	}
133	
134	function alikeComponentsBasePremium(count: number): number {
135	  const formsBlock = count === COMPONENT_BLOCK_SIZE;
136	  return formsBlock
137	    ? COMPONENT_BLOCK_BASE_PREMIUM
138	    : count * COMPONENT_BASE_PREMIUM;
139	}
140	
141	function componentsBasePremium(items: Item[]): number {
142	  const components = items.filter((item) => isComponent(item.type));
143	  let total = 0;
144	  for (const count of countByType(components).values()) {
145	    total += alikeComponentsBasePremium(count);
146	  }
147	  return total;
148	}
149	
150	function isCursed(item: Item): boolean {
151	  return item.cursed === true;
152	}
153	
154	function isHighlyEnchanted(item: Item): boolean {
155	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
156	}
157	
158	function itemSurchargeRate(item: Item): number {
159	  const curse = isCursed(item) ? CURSE_SURCHARGE_RATE : 0;
160	  const enchantment = isHighlyEnchanted(item)
161	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
162	    : 0;
163	  return curse + enchantment;
164	}
165	
166	function itemSurcharges(item: Item): number {
167	  return basePremiumOf(item) * itemSurchargeRate(item);
168	}
169	
170	function isLongStandingCustomer(customer: Customer): boolean {
171	  return customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
172	}
173	
174	function policyModifierRate(history: CustomerHistory): number {
175	  const loyalty = isLongStandingCustomer(history.customer)
176	    ? -LOYALTY_DISCOUNT_RATE
177	    : 0;
178	  const followUp = history.isFollowUpContract()
179	    ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE
180	    : 0;
181	  return loyalty + followUp + FIRST_INSURANCE_SURCHARGE_RATE;
182	}
183	
184	class CustomerHistory {
185	  private contracts = 0;
186	
187	  constructor(readonly customer: Customer) {}
188	
189	  isFollowUpContract(): boolean {
190	    return this.contracts > 0;
191	  }
192	
193	  recordContract(): void {
194	    this.contracts += 1;
195	  }
196	}
197	
198	function insuranceValueOf(item: Item): number {
199	  return isComponent(item.type)
200	    ? COMPONENT_INSURANCE_VALUE
201	    : MAIN_ITEM_PRICE_LIST[item.type].insuranceValue;
202	}
203	
204	function isDeeplyEnchanted(item: Item): boolean {
205	  return (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT;
206	}
207	
208	// Clause precedence: the deeply-enchanted clause settles at 50 %, and the
209	// specification gives it precedence where both clauses apply. The
210	// dragon-material clause reimburses in full -- the same as an item with no
211	// clause at all -- so under the specified rates it needs no branch of its own.
212	function reimbursementRateFor(item: Item): number {
213	  return isDeeplyEnchanted(item)
214	    ? REDUCED_REIMBURSEMENT_RATE
215	    : FULL_REIMBURSEMENT_RATE;
216	}
217	
218	function requireReportableDamage(damage: Damage): void {
219	  if (damage.amount < 0) {
220	    throw new Error(
221	      `A damage amount cannot be negative, but ${damage.amount} was reported`,
222	    );
223	  }
224	}
225	
226	function reimbursementFor(item: Item, damageAmount: number): number {
227	  return damageAmount * reimbursementRateFor(item) - DEDUCTIBLE_PER_DAMAGE;
228	}
229	
230	// Each damage entry is settled against a distinct insured item, so a policy
231	// cannot pay twice for one insured object.
232	class PolicyCoverage {
233	  private readonly unclaimed: Item[];
234	
235	  constructor(items: Item[]) {
236	    this.unclaimed = [...items];
237	  }
238	
239	  claimItemFor(damage: Damage): Item {
240	    const index = this.unclaimed.findIndex(
241	      (candidate) => candidate.type === damage.itemType,
242	    );
243	    if (index === -1) {
244	      throw new Error(
245	        `The policy does not cover a further item of type "${damage.itemType}"`,
246	      );
247	    }
248	    return this.unclaimed.splice(index, 1)[0];
249	  }
250	}
