252	class Policy {
253	  private remainingCap: number;
254	
255	  constructor(readonly items: Item[]) {
256	    const insuranceSum = items.reduce(
257	      (sum, item) => sum + insuranceValueOf(item),
258	      0,
259	    );
260	    this.remainingCap = insuranceSum * CAP_MULTIPLIER;
261	  }
262	
263	  settle(incident: Incident): ClaimResult {
264	    incident.damages.forEach(requireReportableDamage);
265	    const coverage = new PolicyCoverage(this.items);
266	    const desired = incident.damages.reduce(
267	      (sum, damage) =>
268	        sum + reimbursementFor(coverage.claimItemFor(damage), damage.amount),
269	      0,
270	    );
271	    const payout = roundPayoutInOfficeFavour(
272	      Math.min(desired, this.remainingCap),
273	    );
274	    this.remainingCap -= payout;
275	    return { payout, remainingCap: this.remainingCap };
276	  }
277	}
278	
279	function settleClaim(
280	  policiesByStep: Map<number, Policy>,
281	  step: ClaimStep,
282	): ClaimResult {
283	  const policy = policiesByStep.get(step.policy);
284	  if (policy === undefined) {
285	    throw new Error(`Step ${step.policy} did not issue a policy`);
286	  }
287	  return policy.settle(step.incident);
288	}
