298	function quote(items: Item[], history: CustomerHistory): QuoteResult {
299	  items.forEach((item) => requireInsurable(item.type));
300	  const mainItems = items.filter((item) => !isComponent(item.type));
301	  const base =
302	    mainItems.reduce((sum, item) => sum + basePremiumOf(item), 0) +
303	    componentsBasePremium(items);
304	  const surcharges = items.reduce(
305	    (sum, item) => sum + itemSurcharges(item),
306	    0,
307	  );
308	  const policyModifiers = base * policyModifierRate(history);
309	  const premium = base + surcharges + policyModifiers + PROCESSING_FEE;
310	  return { premium: roundPremiumInOfficeFavour(premium) };
311	}
312	
313	export function runScenario(scenario: Scenario): StepResult[] {
314	  const history = new CustomerHistory(scenario.customer);
315	  const policiesByStep = new Map<number, Policy>();
316	  return scenario.steps.map((step, stepIndex) => {
317	    if (step.op === "claim") {
318	      return settleClaim(policiesByStep, step);
319	    }
320	    const result = quote(step.items, history);
321	    policiesByStep.set(stepIndex, new Policy(step.items));
322	    history.recordContract();
323	    return result;
324	  });
325	}

