 62	  enchantment?: number;
 63	  cursed?: boolean;
 64	}
 65	
 66	export interface QuoteStep {
 67	  op: "quote";
 68	  items: Item[];
 69	}
 70	
 71	export interface Damage {
 72	  itemType: string;
 73	  amount: number;
 74	}
 75	
 76	export interface Incident {
 77	  cause: string;
 78	  damages: Damage[];
 79	}
